using System.IO;using UnityEngine;using UnityEngine.Rendering.Universal;public static class CaptureSnowAtlas{public static object Main(){var original=GameObject.Find("Main Camera").GetComponent<Camera>();var go=new GameObject("Review capture");var cam=go.AddComponent<Camera>();cam.CopyFrom(original);cam.enabled=false;cam.transform.position=new Vector3(-35,36,-10);cam.orthographicSize=13.37f;cam.aspect=1152f/640f;cam.cullingMask=original.cullingMask&~(1<<5);var data=go.AddComponent<UniversalAdditionalCameraData>();data.renderType=CameraRenderType.Base;data.SetRenderer(0);data.renderPostProcessing=false;var rt=new RenderTexture(1152,640,24);var old=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1152,640,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1152,640),0,0);tex.Apply();File.WriteAllBytes("output/scene-review/snow-atlas-check.png",tex.EncodeToPNG());RenderTexture.active=old;cam.targetTexture=null;rt.Release();Object.DestroyImmediate(tex);Object.DestroyImmediate(rt);Object.DestroyImmediate(go);return "Captured final";}}



